<script lang="ts">
	import { onMount } from 'svelte';
	import { request } from './api';
	import { AlertBanner, PageHeader, RefreshButton } from './ui';
type Product={id:string;sku:string;name:string;price_cents:number;stock_qty:number};type Sale={id:string;receipt_number:string;status:string;subtotal_cents:number;discount_cents:number;tax_cents:number;total_cents:number;created_at:string;payment_method:string}; type CartLine=Product & {quantity:number};
	let products=$state<Product[]>([]),sales=$state<Sale[]>([]),cart=$state<CartLine[]>([]),sku=$state(''),name=$state(''),priceRupiah=$state<number|null>(null),stock=$state<number|null>(null),paymentMethod=$state('cash'),discountRupiah=$state<number|null>(null),taxRupiah=$state<number|null>(null),error=$state(''),notice=$state(''),saving=$state(false),loading=$state(true);
	const money=(v:number)=>new Intl.NumberFormat('id-ID',{style:'currency',currency:'IDR',maximumFractionDigits:0}).format(v/100);const cents=(v:number|null)=>Math.round(Number(v??0)*100);const failure=(e:unknown)=>e instanceof Error?e.message:'Perubahan tidak dapat disimpan.';let cartSubtotal=$derived(cart.reduce((sum,item)=>sum+item.price_cents*item.quantity,0));let cartTotal=$derived(cartSubtotal-cents(discountRupiah)+cents(taxRupiah));
	async function load(){loading=true;try{const x=await request<{products:Product[];sales:Sale[]}>('/v1/admin/pos');products=x.products;sales=x.sales;}catch(e){error=failure(e);}finally{loading=false;}}
	async function run(label:string,task:()=>Promise<void>){error='';notice='';saving=true;try{await task();notice=`${label} berhasil disimpan.`;await load();}catch(e){error=failure(e);}finally{saving=false;}}
	function add(){return run('Produk',async()=>{if(cents(priceRupiah)<0||Number(stock)<0)throw new Error('Harga dan stok tidak boleh negatif.');await request('/v1/admin/pos/products',{method:'POST',body:JSON.stringify({sku,name,price_cents:cents(priceRupiah),stock_qty:Number(stock)})});sku='';name='';priceRupiah=null;stock=null;});}
	function addToCart(product:Product){const found=cart.find((item)=>item.id===product.id);if(found){if(found.quantity<product.stock_qty)found.quantity+=1;cart=[...cart];return;}cart=[...cart,{...product,quantity:1}];}
	function quantity(id:string,change:number){cart=cart.flatMap((item)=>item.id!==id?[item]:item.quantity+change<1?[]:[{...item,quantity:Math.min(item.stock_qty,item.quantity+change)}]);}
	function checkout(){return run('Transaksi',async()=>{if(!cart.length)throw new Error('Masukkan minimal satu produk ke keranjang.');if(cents(discountRupiah)>cartSubtotal)throw new Error('Diskon tidak boleh lebih besar dari subtotal.');await request('/v1/admin/pos',{method:'POST',body:JSON.stringify({lines:cart.map(({id,quantity})=>({product_id:id,quantity})),payment_method:paymentMethod,discount_cents:cents(discountRupiah),tax_cents:cents(taxRupiah)})});cart=[];discountRupiah=null;taxRupiah=null;});}
	function refund(sale:Sale){return run('Retur',()=>request(`/v1/admin/pos/sales/${sale.id}/refund`,{method:'POST',body:JSON.stringify({note:'Retur dari kasir'})}));}
	function receiptPdf(sale:Sale){window.open(`/v1/admin/pos/sales/${sale.id}/receipt.pdf`,'_blank','noopener,noreferrer');}
	onMount(load);
</script>
<main class="workspace-page pos-page"><PageHeader title="Toko POS" description="Katalog, stok, kasir multi-item, retur, dan receipt dalam satu workspace." backHref="/admin/dashboard">{#snippet actions()}<RefreshButton onclick={load} disabled={saving||loading} label="Muat ulang" />{/snippet}</PageHeader>{#if error}<AlertBanner title="Transaksi belum tersimpan" message={error}/>{/if}{#if notice}<AlertBanner variant="success" message={notice}/>{/if}
<div class="grid"><section class="panel"><h2>Produk baru</h2><form novalidate onsubmit={(e)=>{e.preventDefault();void add();}}><label>SKU<input bind:value={sku} required maxlength="100" placeholder="Contoh: KOPI-001"/></label><label>Nama produk<input bind:value={name} required maxlength="180" placeholder="Contoh: Kopi susu"/></label><div class="twocol"><label>Harga (Rp)<input bind:value={priceRupiah} type="number" min="0" step="1" required placeholder="0"/></label><label>Stok awal<input bind:value={stock} type="number" min="0" step="1" required placeholder="0"/></label></div><button disabled={saving}>Simpan produk</button></form></section>
<section class="panel"><h2>Keranjang kasir</h2><div class="cart">{#each cart as item(item.id)}<article><div><strong>{item.name}</strong><small>{money(item.price_cents)} × {item.quantity}</small></div><div class="cart-actions"><button class="quiet compact" onclick={()=>quantity(item.id,-1)} aria-label={`Kurangi ${item.name}`}>−</button><strong>{item.quantity}</strong><button class="quiet compact" onclick={()=>quantity(item.id,1)} disabled={item.quantity>=item.stock_qty} aria-label={`Tambah ${item.name}`}>+</button></div></article>{:else}<p class="empty">Pilih produk dari katalog untuk memulai transaksi.</p>{/each}</div><div class="checkout"><label>Diskon (Rp)<input bind:value={discountRupiah} type="number" min="0" step="1" placeholder="0"/></label><label>Pajak (Rp)<input bind:value={taxRupiah} type="number" min="0" step="1" placeholder="0"/></label><small>Subtotal {money(cartSubtotal)} · Total {money(cartTotal)}</small><select bind:value={paymentMethod} aria-label="Metode pembayaran"><option value="cash">Tunai</option><option value="transfer">Transfer</option><option value="qris">QRIS</option></select><button disabled={saving||!cart.length} onclick={()=>void checkout()}>Bayar & buat receipt</button></div></section></div>
<section class="panel"><h2>Katalog</h2><div class="catalog">{#each products as item(item.id)}<article><div><strong>{item.name}</strong><small>{item.sku} · stok tersedia {item.stock_qty}</small></div><div><strong>{money(item.price_cents)}</strong><button class="quiet compact" disabled={saving||item.stock_qty<1} onclick={()=>addToCart(item)}>Tambah</button></div></article>{:else}<p class="empty">Belum ada produk.</p>{/each}</div></section>
<section class="panel"><h2>Receipt terbaru</h2><div class="catalog">{#each sales as sale(sale.id)}<article><div><strong>{sale.receipt_number}</strong><small>{new Date(sale.created_at).toLocaleString('id-ID')} · {sale.payment_method}</small></div><div><strong>{money(sale.total_cents)}</strong><div class="receipt-actions"><button class="quiet compact" onclick={()=>receiptPdf(sale)}>PDF receipt</button>{#if sale.status==='paid'}<button class="quiet compact" disabled={saving} onclick={()=>void refund(sale)}>Retur</button>{/if}</div></div></article>{:else}<p class="empty">Belum ada transaksi.</p>{/each}</div></section></main>
<style>.pos-page{display:grid;gap:12px}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.panel{padding:14px;border-radius:var(--radius)}h2{margin:0 0 10px;font-size:14px}form{display:grid;gap:9px}label{display:grid;gap:4px;font-size:11px;font-weight:700}.twocol{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}.catalog,.cart{border-top:1px solid var(--line)}article{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:9px 0;border-bottom:1px solid var(--line)}small,.empty{display:block;color:var(--muted);font-size:11px}.catalog article>div:last-child{text-align:right}.cart-actions,.receipt-actions{display:flex;align-items:center;gap:6px}.checkout{display:grid;gap:8px;margin-top:12px;padding-top:12px;border-top:1px solid var(--line)}.compact{min-height:30px!important;padding:4px 8px!important;font-size:11px!important}@media(max-width:720px){.grid,.twocol{grid-template-columns:1fr}}</style>
